TRACKS[0].units.push({name:'Unit 4 · Thinking Like an Engineer',lessons:[
{name:'Recursion',tip:'A recursive method calls itself on a smaller input. It needs a base case that stops the recursion, and each call must move toward it. Every call gets its own stack frame; too many frames = StackOverflowError.',ex:[
O('static int sum(int n) {\n    return n == 0 ? 0 : n + sum(n - 1);\n}\n// in main:\nSystem.out.println(sum(4));',['10','4','24','0'],0,'4 + 3 + 2 + 1 + 0 = 10. The base case n == 0 stops the chain.'),
M('A recursive method has no base case. What happens when it runs?',['It returns 0','StackOverflowError','Infinite loop that never crashes','Compile error'],1,'Each call adds a stack frame until the stack runs out.'),
O('static void down(int n) {\n    if (n == 0) return;\n    System.out.print(n);\n    down(n - 1);\n}\n// in main:\ndown(3);',['123','321','3210','0123'],1,'It prints BEFORE recursing, so values come out in calling order: 3, 2, 1.'),
O('static void up(int n) {\n    if (n == 0) return;\n    up(n - 1);\n    System.out.print(n);\n}\n// in main:\nup(3);',['321','123','0123','3'],1,'It prints AFTER the recursive call returns, so the deepest call (1) prints first.'),
O('static int pow(int b, int e) {\n    return e == 0 ? 1 : b * pow(b, e - 1);\n}\n// in main:\nSystem.out.println(pow(2, 5));',['10','32','25','64'],1,'2 × 2 × 2 × 2 × 2 × 1 = 32.'),
F('Complete the base case.','static int fact(int n) {\n    if (n ___ 1) return 1;\n    return n * fact(n - 1);\n}',['<=','>','==','!='],0,'n <= 1 also safely handles 0 (0! = 1).'),
B('This should return a string\'s length recursively. Tap the bug.',['static int len(String s) {','    if (s.isEmpty()) return 0;','    return 1 + len(s);','}'],2,'len(s) never gets smaller, so it recurses forever. It should be len(s.substring(1)).'),
O('static String rev(String s) {\n    return s.isEmpty() ? "" : rev(s.substring(1)) + s.charAt(0);\n}\n// in main:\nSystem.out.println(rev("abc"));',['abc','cba','bca','a'],1,'rev("abc") = rev("bc") + "a" = (rev("c") + "b") + "a" = "cba".')]},
{name:'Big-O & Searching',tip:'Big-O describes how running time grows as input size n grows, ignoring constants. O(1) constant, O(log n) halving, O(n) one pass, O(n log n) good sorting, O(n²) nested loops. Binary search needs SORTED data.',ex:[
M('O(1) means the operation…',['Takes 1 millisecond','Takes the same time no matter how big n gets','Runs once per element','Is always the fastest possible'],1,'Constant time: array index access, HashMap.get on average.'),
M('Worst case of searching an unsorted array for a value?',['O(1)','O(log n)','O(n)','O(n²)'],2,'You may have to look at every element.'),
O('int ops = 0;\nfor (int i = 1; i < 16; i *= 2) ops++;\nSystem.out.println(ops);',['16','4','5','8'],1,'i takes 1, 2, 4, 8 — then 16 stops the loop. Doubling = logarithmic.'),
M('Which grows fastest as n gets large?',['O(n log n)','O(n²)','O(n)','O(log n)'],1,'For n = 1,000: n² = 1,000,000 vs n log n ≈ 10,000.'),
O('int[] a = {2, 4, 6, 8, 10};\nSystem.out.println(Arrays.binarySearch(a, 8));',['8','3','4','-1'],1,'binarySearch returns the INDEX of the match: 8 is at index 3.'),
M('list.contains(x): ArrayList vs HashSet?',['Both O(1)','ArrayList O(n), HashSet O(1) on average','ArrayList O(1), HashSet O(n)','Both O(log n)'],1,'ArrayList scans; HashSet hashes straight to a bucket. Big win for repeated lookups.'),
O('int c = 0;\nfor (int i = 0; i < 3; i++)\n    for (int j = 0; j < 3; j++)\n        c++;\nSystem.out.println(c);',['6','9','3','27'],1,'3 × 3 = 9. Two nested loops over n = O(n²).'),
M('O(2n + 10) simplifies to…',['O(2n)','O(n)','O(n + 10)','O(1)'],1,'Big-O drops constant factors and lower-order terms.')]},
{name:'Threads & Concurrency',tip:'A thread is an independent path of execution. start() launches a new thread; join() waits for it to finish. Shared mutable data needs protection (synchronized, locks, or atomic classes), otherwise you get race conditions.',ex:[
M('What does thread.start() do that thread.run() does not?',['Nothing — they are the same','Runs the code on a NEW thread','Runs it twice','Waits for the thread to finish'],1,'Calling run() directly just executes the method on the current thread.'),
O('Thread t = new Thread(() -> System.out.print("B"));\nt.start();\nt.join();\nSystem.out.println("A");',['AB','BA','A','Unpredictable'],1,'join() blocks main until t finishes, so B is always printed first.'),
O('AtomicInteger n = new AtomicInteger();\nRunnable r = () -> { for (int i = 0; i < 1000; i++) n.incrementAndGet(); };\nThread a = new Thread(r), b = new Thread(r);\na.start(); b.start();\na.join(); b.join();\nSystem.out.println(n.get());',['2000','1000','Less than 2000','Unpredictable'],0,'incrementAndGet is atomic, so no updates are lost. With a plain int++ the result could be below 2000.'),
M('A race condition is…',['A thread that runs too fast','A bug where the result depends on the timing of threads touching shared data','A deadlock','A compile error'],1,'Classic example: two threads doing count++ at the same time.'),
F('Only one thread at a time may run this method on the same object.','public ___ void increment() { count++; }',['synchronized','volatile','static','atomic'],0,'synchronized takes the object\'s lock before entering.'),
M('Why use an ExecutorService instead of new Thread() for every task?',['It is required by Java','It reuses a pool of threads and manages task queuing','It makes code single-threaded','It removes the need for synchronization'],1,'Creating threads is expensive; pools reuse them.'),
M('Two threads each hold one lock and wait forever for the other\'s lock. This is…',['A race condition','A deadlock','Starvation','Garbage collection'],1,'Avoid it by always acquiring locks in the same order.'),
M('In JavaFX or Swing, why do slow tasks go on a background thread?',['To use more memory','So the UI thread stays free to repaint and respond','Because the UI thread can\'t do math','It is optional style'],1,'Blocking the UI thread freezes the app. Update the UI afterwards on the UI thread.')]}]});
TRACKS[0].units.push({name:'Unit 5 · Professional Java',lessons:[
{name:'OOP Design & SOLID',tip:'Good design keeps code easy to change. SOLID: Single responsibility, Open/closed, Liskov substitution, Interface segregation, Dependency inversion. Program to interfaces, and prefer composition ("has-a") over deep inheritance ("is-a").',ex:[
M('The Single Responsibility Principle says a class should…',['Have only one method','Have one reason to change','Be used by one other class','Never extend another class'],1,'A class that parses, validates AND saves has three reasons to change. Split it.'),
M('"Open for extension, closed for modification" means…',['Make every field public','Add new behavior by adding new classes, not by editing working code','Never write subclasses','Close files after opening them'],1,'e.g. add a new Shape class instead of growing a giant switch in an existing method.'),
O('interface Shape { double area(); }\nrecord Sq(double s) implements Shape { public double area() { return s * s; } }\nrecord Circle(double r) implements Shape { public double area() { return 3 * r * r; } }\n// in main:\nList<Shape> shapes = List.of(new Sq(2), new Circle(1));\ndouble total = 0;\nfor (Shape sh : shapes) total += sh.area();\nSystem.out.println(total);',['7.0','7','5.0','Compile error'],0,'4.0 + 3.0 = 7.0 (a double). The loop never needs to know which concrete Shape it has: that\'s polymorphism.'),
M('"A Car has an Engine" is best modeled with…',['Car extends Engine','Composition: Car has a field of type Engine','Engine extends Car','A static method'],1,'has-a = composition. is-a = inheritance. Composition is usually more flexible.'),
M('Liskov Substitution: a subclass object should…',['Override every method','Work anywhere its parent type is expected without surprises','Be final','Have more fields than its parent'],1,'The classic violation: Square extends Rectangle, but setWidth on a Square also changes height.'),
M('Dependency Inversion suggests OrderService should depend on…',['A concrete MySqlDatabase class','A Database interface passed in (e.g. via the constructor)','A global static variable','Nothing at all'],1,'Depending on an abstraction lets you swap in a test fake or another database.'),
O('abstract class Animal {\n    String speak() { return "..."; }\n    String intro() { return "I say " + speak(); }\n}\nclass Dog extends Animal { String speak() { return "Woof"; } }\n// in main:\nAnimal a = new Dog();\nSystem.out.println(a.intro());',['I say ...','I say Woof','Woof','Compile error'],1,'intro() is inherited, but its call to speak() is dispatched to the runtime type: Dog.'),
F('Logger promises to provide everything Printer declares.','class Logger ___ Printer {\n    public void print(String s) { System.out.println(s); }\n}',['implements','extends','inherits','uses'],0,'Classes implement interfaces; they extend classes.')]},
{name:'Files & I/O',tip:'java.nio.file is the modern file API: Path.of(...) names a file, Files.readString / readAllLines / writeString do simple I/O. Most I/O methods throw the checked IOException. Use try-with-resources so readers and streams always close.',ex:[
M('What does try-with-resources guarantee?',['The file exists','The resource is closed automatically, even if an exception is thrown','No exceptions happen','The file is read faster'],1,'try (var r = Files.newBufferedReader(p)) { ... } calls r.close() for you.'),
F('Read every line of a text file into a list.','List<String> lines = Files.___(Path.of("data.txt"));',['readAllLines','readLines','open','getLines'],0,'Files.readAllLines returns List<String>. Fine for small files.'),
O('Path p = Files.createTempFile("demo", ".txt");\nFiles.writeString(p, "a\\nb\\nc");\nSystem.out.println(Files.readAllLines(p).size());',['1','3','5','0'],1,'Three lines separated by \\n.'),
M('Files.readString(path) throws IOException. Because it is a checked exception you must…',['Ignore it','Catch it or declare throws IOException','Use a different method','Wrap it in a String'],1,'The compiler forces you to handle checked exceptions.'),
O('Path p = Files.createTempFile("demo", ".txt");\nFiles.writeString(p, "hi");\nFiles.writeString(p, "yo");\nSystem.out.println(Files.readString(p));',['hi','yo','hiyo','Exception'],1,'writeString replaces the file contents by default.'),
O('Path p = Files.createTempFile("demo", ".txt");\nFiles.writeString(p, "hi");\nFiles.writeString(p, "!", StandardOpenOption.APPEND);\nSystem.out.println(Files.readString(p));',['!','hi!','hi','!hi'],1,'APPEND adds to the end instead of overwriting.'),
O('Path p = Path.of("docs", "notes.txt");\nSystem.out.println(p.getFileName());',['docs','notes.txt','docs/notes.txt','notes'],1,'getFileName() is the last part of the path.'),
M('Which reads a HUGE log file line by line without loading it all into memory?',['Files.readAllLines(p)','Files.readString(p)','Files.lines(p) inside try-with-resources','new String(Files.readAllBytes(p))'],2,'Files.lines returns a lazy Stream<String>; the others load everything at once.')]},
{name:'Testing with JUnit',tip:'A unit test checks one small piece of code in isolation. JUnit 5: mark methods with @Test, use assertEquals(expected, actual), assertTrue, assertThrows. Structure tests as Arrange, Act, Assert. Fake slow or external dependencies with mocks.',ex:[
M('A unit test should…',['Test the whole app through the UI','Check one small unit of code in isolation, quickly','Only run in production','Print results for a human to read'],1,'Fast, focused tests can run on every change.'),
F('Mark this method as a JUnit test.','@___\nvoid addsTwoNumbers() {\n    assertEquals(4, Calc.add(2, 2));\n}',['Test','Check','Run','Unit'],0,'@Test (org.junit.jupiter.api.Test).'),
M('In assertEquals(a, b), which argument is the expected value?',['The first (a)','The second (b)','Either; it does not matter','Neither'],0,'assertEquals(expected, actual). Swapping them gives confusing failure messages.'),
M('Arrange-Act-Assert means…',['Write tests after release','Set up data, call the code, then check the result','Assert first, then run the code','Use three test classes'],1,'Keeps every test readable and consistent.'),
M('How do you test that withdraw(-5) throws IllegalArgumentException?',['try/catch and print','assertThrows(IllegalArgumentException.class, () -> acct.withdraw(-5))','assertEquals(null, acct.withdraw(-5))','You cannot test exceptions'],1,'assertThrows also returns the exception so you can check its message.'),
M('@BeforeEach runs…',['Once before all tests','Before every single test method','After each test','Only when a test fails'],1,'Use it to create fresh objects so tests do not affect each other.'),
M('Why use a mock (e.g. Mockito) for a PaymentGateway in a unit test?',['To charge real cards','To replace a slow/external dependency with a controllable fake','To make the test slower','Mocks are required by JUnit'],1,'Your test checks YOUR logic, not the payment provider.'),
B('This test can never fail. Tap the problem.',['@Test','void sortsNumbers() {','    List<Integer> xs = new ArrayList<>(List.of(3, 1, 2));','    Collections.sort(xs);','    System.out.println(xs);','}'],4,'Printing is not asserting. Use assertEquals(List.of(1, 2, 3), xs).')]},
{name:'Interview Patterns',tip:'Most coding-interview problems reuse a few patterns: two pointers (walk from both ends), hashing (HashMap/HashSet for O(1) lookups), sliding window (reuse the previous window\'s sum), and binary search on sorted data.',ex:[
O('static boolean isPal(String s) {\n    int i = 0, j = s.length() - 1;\n    while (i < j) if (s.charAt(i++) != s.charAt(j--)) return false;\n    return true;\n}\n// in main:\nSystem.out.println(isPal("racecar") + " " + isPal("ab"));',['true true','true false','false false','false true'],1,'Two pointers move toward the middle comparing characters: O(n) time, O(1) space.'),
O('int[] nums = {2, 7, 11, 15};\nint target = 9;\nMap<Integer, Integer> seen = new HashMap<>();\nfor (int i = 0; i < nums.length; i++) {\n    Integer j = seen.get(target - nums[i]);\n    if (j != null) System.out.println(j + "," + i);\n    seen.put(nums[i], i);\n}',['0,1','1,0','2,7','Nothing'],0,'Classic Two Sum: at i = 1 we need 2, which was seen at index 0.'),
M('Time complexity of that HashMap Two Sum?',['O(n²)','O(n)','O(log n)','O(n log n)'],1,'One pass with O(1) average lookups, versus O(n²) for checking every pair.'),
O('int[] a = {1, 4, 2, 10, 2, 3};\nint k = 3, sum = 0, best;\nfor (int i = 0; i < k; i++) sum += a[i];\nbest = sum;\nfor (int i = k; i < a.length; i++) {\n    sum += a[i] - a[i - k];\n    best = Math.max(best, sum);\n}\nSystem.out.println(best);',['15','16','17','14'],1,'Window sums: 7, 16, 14, 15. Sliding window updates each sum in O(1).'),
O('String s = "swiss";\nMap<Character, Integer> freq = new LinkedHashMap<>();\nfor (char c : s.toCharArray()) freq.merge(c, 1, Integer::sum);\nfor (var e : freq.entrySet())\n    if (e.getValue() == 1) { System.out.println(e.getKey()); break; }',['s','w','i','Nothing'],1,'Counts: s=3, w=1, i=1. LinkedHashMap keeps insertion order, so w is first.'),
O('int[] a = {1, 2, 3, 4};\nfor (int i = 0, j = a.length - 1; i < j; i++, j--) {\n    int t = a[i]; a[i] = a[j]; a[j] = t;\n}\nSystem.out.println(Arrays.toString(a));',['[1, 2, 3, 4]','[4, 3, 2, 1]','[4, 2, 3, 1]','[2, 1, 4, 3]'],1,'Swap ends and move inward: in-place reversal.'),
M('Fastest typical way to check an int array for duplicates?',['Nested loops comparing every pair','Add each value to a HashSet; add() returns false on a duplicate','Sort, then binary search each value','Convert to a String'],1,'O(n) time with O(n) extra space. Sorting first is O(n log n) with less memory.'),
A('Arrange the binary search body (a is sorted, find x).',['int lo = 0, hi = a.length - 1;','while (lo <= hi) {','    int mid = (lo + hi) >>> 1;','    if (a[mid] == x) return mid;','    if (a[mid] < x) lo = mid + 1; else hi = mid - 1;','}','return -1;'],'Halve the range each step. >>> 1 avoids int overflow for huge arrays.')]}]});
L('swift',0,{name:'Enums, Switch & Structs',tip:'Swift enums can carry raw values or associated values, and switch must be exhaustive (cover every case or add default). Struct methods that change properties are marked mutating. Computed properties calculate a value instead of storing it.',ex:[
O('enum Dir { case north, south }\nlet d = Dir.north\nswitch d {\ncase .north: print("N")\ncase .south: print("S")\n}',['N','S','north','Compile error'],0,'The switch matches .north. No default needed because every case is covered.'),
O('enum Coin: Int { case penny = 1, nickel = 5 }\nprint(Coin.nickel.rawValue)',['nickel','5','1','Optional(5)'],1,'rawValue returns the Int backing the case.'),
M('A switch over an enum without default does not cover every case. What happens?',['It silently does nothing','Compile error: switch must be exhaustive','Runtime crash','Falls through to the next case'],1,'Swift checks exhaustiveness at compile time, and cases never fall through implicitly.'),
O('enum Shape { case circle(Double), square(Double) }\nlet s = Shape.square(3)\nif case .square(let side) = s { print(side * side) }',['9','9.0','3.0','Nothing'],1,'Associated values are extracted by pattern matching. side is a Double, so the result prints 9.0.'),
O('struct Counter {\n    var n = 0\n    mutating func inc() { n += 1 }\n}\nvar c = Counter()\nc.inc(); c.inc()\nprint(c.n)',['0','1','2','Compile error'],2,'mutating lets a struct method change its own properties. c must be var.'),
O('struct Rect {\n    var w = 2.0, h = 3.0\n    var area: Double { w * h }\n}\nprint(Rect().area)',['6','6.0','5.0','nil'],1,'area is a computed property: recalculated every time it is read.'),
O('let score = 85\nswitch score {\ncase 90...: print("A")\ncase 80..<90: print("B")\ndefault: print("C")\n}',['A','B','C','AB'],1,'Swift switch can match ranges. 85 falls in 80..<90.'),
F('Exit early when the optional is nil.','func greet(_ name: String?) {\n    ___ let name else { return }\n    print("Hi " + name)\n}',['guard','if','when','unless'],0,'guard let unwraps and requires the else branch to exit the scope. name stays available afterwards.')]});
